local cs_coroutine = import('XLua.cs_coroutine')
local WaitForSeconds = CS.UnityEngine.WaitForSeconds
local UIModule = CS.Engine.UI.UIModule



local worldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)

---@class BtnFightReadyService
local BtnFightReadyService = Class("BtnFightReadyService")

function BtnFightReadyService.new(facade)
    local obj = BtnFightReadyService.New()
    obj.facade = facade
    obj.CoClick = nil
    return obj
end

function BtnFightReadyService:UpdateInfo()
    local isOpen = worldBossComponent:IsOpen()
    if not isOpen then
        CfUtils.SetActive(self.facade.FontStyleButton.transform:Find("ImgBlack").gameObject, true)
    end

    SetButtonAction(self.facade.FontStyleButton, Bind(self, self.OnClick))
end

function BtnFightReadyService:OnClick()
    if self.CoClick then
        cs_coroutine.stop(self.CoClick)
        self.CoClick = nil
    end
    self.CoClick = cs_coroutine.start(function()
        if not worldBossComponent:IsOpen() then
            GameUtils.Toast(localize("活动未开启"))
            return
        end

        UIModule.OpenDialog({
            id = Constants.UITypeIds.UIFightTeamChoose,
            parameters = {
                levelId = self.facade.worldBossPlanModelProxy:Range()
            }
        }, {
            { id = Constants.UITypeIds.UIWorldBossMainDialog }
        })
        self.CoClick = nil
    end)
end

function BtnFightReadyService:Dispose()
    if self.CoClick then
        cs_coroutine.stop(self.CoClick)
        self.CoClick = nil
    end
end

return BtnFightReadyService